package pl.rodzina.terminarz;
import android.content.*;import android.app.*;import android.os.*;
public class ReminderReceiver extends BroadcastReceiver{
 @Override public void onReceive(Context c,Intent i){String title=i.getStringExtra("title");if(title==null)title="Wydarzenie rodzinne";Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"family_events"):new Notification.Builder(c);String eventId=i.getStringExtra("eventId");Intent open=new Intent(c,MainActivity.class);open.putExtra("reminder_event_id",eventId);open.setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent tap=PendingIntent.getActivity(c,i.getIntExtra("id",1),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("Terminarz rodzinny").setContentText(title).setContentIntent(tap).setAutoCancel(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(i.getIntExtra("id",1),b.build());}
}